---@meta
-- Hand-written type definitions for the `rex` global, so lua-language-server
-- can complete and check init.lua. Rex never reads this file and it isn't
-- deployed.
-- API: https://www.superlogical.com/rex/docs/reference/lua
--
-- What depends on the app version (rex.ActionName, the rex.args.* classes,
-- rex.bind, and rex.client.queue) is generated by rex-lua-types into the
-- library that .luarc.json points to.

---@class rex
rex = {}

-- Key bindings

---@class rex.Context
---@field session_id? string
---@field block_id? string
---@field client_id? string
---@field origin? string What triggered the call, such as "timer".
---@field server? string

---@class rex.KeyEvent
---@field keybinding string The key that was pressed.
---@field prefix? string[] For a sequence, the keys pressed before it.

---@alias rex.KeyHandler fun(ctx: rex.Context, ev: rex.KeyEvent): boolean?

---@class rex.Binding
---@field key string The key or sequence, without its mode.
---@field mode? string
---@field action? string `nil` for a function binding.
---@field fn? function `nil` for an action binding.
---@field args? table
---@field source string Where it was bound, such as "keys.lua:3".

---Removes the bindings of a key, in this file and in the client's defaults.
---`target` limits the removal to bindings with that action or function.
---`rex.unbind("mode/key")` also blocks the key in that mode.
---@param key string
---@param target? rex.ActionName|function
---@return integer removed The number of this file's bindings removed.
---@overload fun(mode: { mode: string }) Removes a whole mode.
---@overload fun(binding: rex.Binding): integer Removes one binding returned by `rex.bindings`.
function rex.unbind(key, target) end

---Declares a mode and sets its options.
---@param name string Lowercase letters, digits, underscores, and hyphens.
---@param options? { exclusive?: boolean } An exclusive mode ignores keys it doesn't bind.
function rex.mode(name, options) end

---Returns the bindings made so far, in order.
---@param filter? { key?: string, mode?: string, action?: string }
---@return rex.Binding[]
function rex.bindings(filter) end

---Returns the modes declared or bound so far.
---@return { name: string, exclusive: boolean, source: string }[]
function rex.modes() end

-- Actions

---@alias rex.ArgType
---| "string" | "number" | "integer" | "boolean" | "object" | "array" | "any"
---| "string?" | "number?" | "integer?" | "boolean?" | "object?" | "array?" | "any?"

---@class rex.ActionSpec
---@field name string Lowercase letters, digits, and underscores.
---@field title string Shown in the command palette.
---@field run fun(ctx: rex.Context, args: table): any Its return value is the action's result.
---@field description? string
---@field category? string Groups the action in the palette. Defaults to "Actions".
---@field keywords? string Extra words for search.
---@field args? table<string, rex.ArgType>|table Argument types, or a JSON Schema.
---@field repeats? boolean Run again while the key is held.

---Defines an action that keys, the palette, and `rex.invoke` can run.
---@param spec rex.ActionSpec
function rex.action(spec) end

---Runs an action and returns its result.
---@param name string
---@param args? table
---@return any result
---@return string? err
function rex.invoke(name, args) end

-- rex.client.queue is generated by rex-lua-types.
rex.client = {}

-- Calling Rex. Every call returns a result table, or `nil` and an error
-- message. For a method's arguments, run `rex api describe session.<method>`.

---@alias rex.Call fun(args?: table): table?, string?

---@class rex.session
---@field view rex.Call Return the session's windows, layouts, and blocks.
---@field list_blocks rex.Call List every block and whether it is placed or detached.
---@field list_clients rex.Call List the clients attached to the session.
---@field describe_block rex.Call Return a block's placement and the methods it offers.
---@field new_window rex.Call Create a window from a layout.
---@field new_split rex.Call Create a split beside an existing block.
---@field new_block rex.Call Create a block without placing it in a layout.
---@field new_layer rex.Call Create a floating layer in a window.
---@field close_window rex.Call Close a window and every block in it.
---@field close_layer rex.Call Close a floating layer and every block in it.
---@field move_block rex.Call Move a block into a new split beside another.
---@field swap_blocks rex.Call Exchange the positions of two blocks.
---@field detach_block rex.Call Remove a block from its layout without closing it.
---@field float_block rex.Call Move a tiled block into a new floating layer.
---@field zoom_block rex.Call Toggle or set whether a block fills its window.
---@field resize_pane rex.Call Move the border between two blocks.
---@field resize_layer rex.Call Set a floating layer's position and size.
---@field raise_layer rex.Call Move a floating layer up the stacking order.
---@field lower_layer rex.Call Move a floating layer down the stacking order.
---@field move_window rex.Call Move a window in the tab order.
---@field focus_block rex.Call Focus a block.
---@field focus_window rex.Call Focus a window.
---@field focus_direction rex.Call Focus the nearest block in a direction.
---@field focus_next_pane rex.Call Focus the next pane.
---@field focus_previous_pane rex.Call Focus the previous pane.
---@field focus_next_window rex.Call Focus the next window.
---@field focus_previous_window rex.Call Focus the previous window.
---@field set_label rex.Call Set the session's label.
---@field set_window_label rex.Call Set a window's label.
---@field set_block_label rex.Call Set a block's label.
---@field attach rex.Call Change which session a script hears events from.
---@field detach rex.Call Change which session a script hears events from.
---@field help rex.Call Describe the methods available through the session.
rex.session = {}

---Calls any server method by its full name. `rex api list` prints them all.
---@param method string Such as "session.list".
---@param args? table
---@return table? result
---@return string? err
function rex.call(method, args) end

---@alias rex.BlockCreator
---| "com.superlogical.terminal"
---| string

---@alias rex.TerminalMethod
---| "format" # Return the screen as text, HTML, or VT sequences.
---| "process" # Describe the terminal's child and foreground processes.
---| "pwd" # Return the working directory the terminal last reported.
---| "title" # Return the terminal's title.
---| "size" # Return the terminal's size in cells and pixels.
---| "write" # Write bytes to the terminal as if they were typed.
---| "reset" # Reset the terminal.
---| "resize" # Request a size for the terminal.
---| "set_theme" # Replace the terminal's default colors.
---| "program_status" # Return the status records programs have reported.
---| "list_dir" # List the directories under a path.
---| string

rex.block = {}

---Calls a method on a block. `block_id` defaults to the current block.
---@param creator rex.BlockCreator The full name of the kind of block.
---@param method rex.TerminalMethod
---@param args? table
---@return table? result
---@return string? err
function rex.block.call(creator, method, args) end

---@class rex.Layout

---@class rex.TerminalOptions
---@field command? string[] The program and its arguments. Without it, an interactive shell starts.
---@field shell? string The shell to use. "none" starts `command` directly.
---@field cwd? string
---@field initial_input? string Text typed into the terminal once it starts.
---@field exit? { on_completion?: boolean } `on_completion = false` keeps the terminal open after its program exits.

rex.layout = {}

---One block, for `new_window`, `new_split`, and `new_layer`.
---@param spec { flavor: string, options?: rex.TerminalOptions|table } `flavor` is such as "com.superlogical.terminal.shell".
---@return rex.Layout
function rex.layout.block(spec) end

---Two layouts split horizontally.
---@param ratio number The share given to `a`, from 0 to 1.
---@param a rex.Layout
---@param b rex.Layout
---@return rex.Layout
function rex.layout.horizontal(ratio, a, b) end

---Two layouts split vertically.
---@param ratio number The share given to `a`, from 0 to 1.
---@param a rex.Layout
---@param b rex.Layout
---@return rex.Layout
function rex.layout.vertical(ratio, a, b) end

-- Hosts and other servers

---@class rex.HostSpec
---@field label string The host's name.
---@field endpoints? string[] Addresses, tried in order.
---@field endpoint? string A single address, in place of `endpoints`.
---@field id? string A stable ID, so the host keeps its identity when renamed.
---@field icon? string An icon name for clients to show.

---Declares another Rex server you connect to.
---@param spec rex.HostSpec
function rex.host(spec) end

---Returns the labels of the other servers available to the running code.
---@return string[]
function rex.servers() end

---@class rex.Server
---@field session rex.session
---@field block { call: fun(creator: rex.BlockCreator, method: rex.TerminalMethod, args?: table): table?, string? }
---@field call fun(method: string, args?: table): table?, string?

---Returns functions whose calls go to another server. Raises for an unknown label.
---@param label string
---@return rex.Server
function rex.server(label) end

-- Running commands, timers, JSON, and logging

---@class rex.ExecOptions
---@field cwd? string Defaults to Rex's own working directory.
---@field env? table<string, string|false> Variables to set. `false` removes one.
---@field clear_env? boolean Start from an empty environment. `env` still applies.
---@field stdin? string Written to the command's standard input.
---@field timeout? number Seconds until SIGTERM, then SIGKILL two seconds later.
---@field stdout? false `false` discards the stream.
---@field stderr? false `false` discards the stream.
---@field text? boolean `false` keeps "\r\n" in the output on Windows.

---@class rex.ExecStartOptions : rex.ExecOptions
---@field stdin? string|true `true` keeps standard input open for `h:write`.
---@field stdout? false|fun(data: string) Called with each piece of output.
---@field stderr? false|fun(data: string) Called with each piece of output.
---@field detach? boolean Let the command outlive the work that started it.

---@class rex.ExecResult
---@field code integer The exit status, or -1 if a signal ended the command.
---@field signal? string The signal's name, such as "SIGTERM".
---@field stdout string
---@field stderr string
---@field timed_out boolean
---@field ok boolean `code` is 0 and the command didn't time out.

---@class rex.ExecHandle
---@field pid integer
local ExecHandle = {}

---Waits for the command to exit. Returns `nil, "timeout"` if `seconds` pass first.
---@param seconds? number
---@return rex.ExecResult?
---@return string? err
function ExecHandle:wait(seconds) end

---Writes to standard input.
---@param data string
---@return true?
---@return string? err
function ExecHandle:write(data) end

function ExecHandle:close_stdin() end

---@param signal? string|integer Defaults to "SIGTERM".
function ExecHandle:kill(signal) end

---@return boolean
function ExecHandle:running() end

---Runs a command and waits for it. A non-zero exit is still a result: check `ok`.
---Returns `nil` and an error message only when the command never ran.
---@class rex.exec
---@overload fun(argv: string[], opts?: rex.ExecOptions): rex.ExecResult?, string?
rex.exec = {}

---Starts a command and returns a handle without waiting.
---@param argv string[]
---@param opts? rex.ExecStartOptions
---@return rex.ExecHandle?
---@return string? err
function rex.exec.start(argv, opts) end

---@class rex.Timer
local Timer = {}

function Timer:cancel() end

---@return boolean
function Timer:active() end

---Calls `fn` once after `seconds`. Script only: `nil` in init.lua.
---@param seconds number
---@param fn fun(ctx: rex.Context)
---@return rex.Timer
function rex.after(seconds, fn) end

---Calls `fn` every `seconds` until cancelled. Script only: `nil` in init.lua.
---@param seconds number
---@param fn fun(ctx: rex.Context)
---@return rex.Timer
function rex.every(seconds, fn) end

rex.json = {}

---@param value any
---@param opts? { indent?: boolean }
---@return string? text
---@return string? err
function rex.json.encode(value, opts) end

---`null` becomes `nil`, and a `null` in an array is dropped.
---@param text string
---@return any value
---@return string? err
function rex.json.decode(text) end

---@alias rex.LogLevel "debug"|"info"|"warn"|"error"

---Writes a log message. `level` defaults to "info".
---@param level rex.LogLevel
---@param message string
---@overload fun(message: string)
function rex.log(level, message) end

-- Scripts run with `rex do` only

---Calls `fn(ctx, ev)` each time `event` happens.
---@param event string
---@param fn fun(ctx: rex.Context, ev: table)
function rex.on(event, fn) end

---Blocks until `event` happens. Returns `nil, "timeout"` if `timeout` seconds pass first.
---@param event string
---@param filter? table|fun(ev: table, ctx: rex.Context): boolean
---@param timeout? number
---@return table? ev
---@return rex.Context|string ctx
---@overload fun(event: string, timeout?: number): table?, rex.Context|string
function rex.wait(event, filter, timeout) end

---@param seconds number May be fractional.
function rex.sleep(seconds) end

---Ends the script. `rex do` exits with `code`, or 0.
---@param code? integer
function rex.stop(code) end

---The script's arguments.
---@type table
rex.args = {}

---@type string
rex.session_id = ""

---@type string?
rex.block_id = nil
